const allItems = $input.all();
const today = new Date().toISOString().split('T')[0];
const normalized = [];
const seen = new Set();

function cleanHtml(str) {
  if (!str) return '';
  return str.replace(/<[^>]*>/g, ' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim().substring(0, 2000);
}

for (const item of allItems) {
  const d = item.json;
  let job = {
    date_found: today,
    source: 'unknown',
    job_title: '',
    company: '',
    job_url: '',
    location_text: '',
    salary: '',
    description: '',
    posted_date: today,
    tags: '',
    job_id: ''
  };

  // RemoteOK — returns array, first item is legal notice
  if (d.position !== undefined && d.company !== undefined && d.slug !== undefined) {
    job.source = 'remoteok';
    job.job_title = d.position || '';
    job.company = d.company || '';
    job.job_url = d.url || `https://remoteok.com/l/${d.slug}`;
    job.location_text = d.location || 'worldwide remote';
    job.salary = d.salary_min ? `$${d.salary_min} - $${d.salary_max}/yr` : '';
    job.description = cleanHtml(d.description || d.position);
    job.posted_date = d.date || today;
    job.tags = Array.isArray(d.tags) ? d.tags.join(', ') : (d.tags || '');
  }
  // Remotive — jobs array item
  else if (d.title !== undefined && d.company_name !== undefined && d.candidate_required_location !== undefined) {
    job.source = 'remotive';
    job.job_title = d.title || '';
    job.company = d.company_name || '';
    job.job_url = d.url || '';
    job.location_text = d.candidate_required_location || '';
    job.salary = d.salary || '';
    job.description = cleanHtml(d.description);
    job.posted_date = d.publication_date || today;
    job.tags = Array.isArray(d.tags) ? d.tags.join(', ') : (d.tags || '');
  }
  // Himalayas JSON API
  else if (d.title !== undefined && d.companyName !== undefined) {
    job.source = 'himalayas';
    job.job_title = d.title || d.role || '';
    job.company = d.companyName || d.company || '';
    job.job_url = d.url || d.applicationUrl || `https://himalayas.app/jobs/${d.slug || d.id}`;
    job.location_text = d.location || d.locationRestrictions || 'worldwide remote';
    job.salary = d.salary || d.salaryRange || '';
    job.description = cleanHtml(d.description);
    job.posted_date = d.createdAt || d.publishedAt || today;
    job.tags = d.skills ? (Array.isArray(d.skills) ? d.skills.join(', ') : d.skills) : '';
  }
  // RSS feeds (WWR, DynamiteJobs, YC)
  else if (d.title !== undefined && d.link !== undefined && (d.pubDate !== undefined || d.isoDate !== undefined)) {
    const src = (d.link || '').includes('weworkremotely') ? 'weworkremotely'
             : (d.link || '').includes('dynamitejobs') ? 'dynamitejobs'
             : (d.link || '').includes('workatastartup') ? 'ycombinator'
             : 'rss_source';
    job.source = src;
    job.job_title = d.title || '';
    job.company = d['dc:creator'] || d.author || '';
    // WWR title format: "COMPANY | JOB TITLE"
    if (src === 'weworkremotely' && job.job_title.includes(' | ')) {
      const parts = job.job_title.split(' | ');
      job.company = parts[0].trim();
      job.job_title = parts.slice(1).join(' | ').trim();
    }
    job.job_url = d.link || '';
    job.location_text = 'worldwide remote';
    job.salary = '';
    job.description = cleanHtml(d.content || d.contentSnippet || d.description || '');
    job.posted_date = d.isoDate || d.pubDate || today;
    job.tags = d.categories ? (Array.isArray(d.categories) ? d.categories.join(', ') : d.categories) : '';
  }
  // YC JSON format
  else if (d.title !== undefined && d.company !== undefined && d.applyUrl !== undefined) {
    job.source = 'ycombinator';
    job.job_title = d.title || '';
    job.company = d.company || '';
    job.job_url = d.applyUrl || d.url || '';
    job.location_text = d.location || 'worldwide remote';
    job.salary = d.equity || '';
    job.description = cleanHtml(d.description);
    job.posted_date = d.createdAt || today;
    job.tags = Array.isArray(d.tags) ? d.tags.join(', ') : '';
  }
  // Wellfound / Otta JSON (add more format detection as needed)
  else if (d.job_title !== undefined && d.job_url !== undefined) {
    job = { ...job, ...d };
  }

  if (!job.job_title || !job.job_url) continue;

  job.job_id = job.job_url;

  const dedupKey = job.job_url;
  if (seen.has(dedupKey)) continue;
  seen.add(dedupKey);

  normalized.push({ json: job });
}

return normalized;

// Build set of existing URLs from Google Sheets
const existing = new Set();
try {
  const sheetsData = $('Read Existing Job URLs').all();
  for (const row of sheetsData) {
    if (row.json.job_url) existing.add(row.json.job_url);
  }
} catch(e) { /* first run — no existing rows */ }

// Taiwan hard reject patterns
const REJECT_PATTERNS = [
  /\bus only\b/i, /\busa only\b/i, /\bunited states only\b/i,
  /\bcanada only\b/i, /\buk only\b/i, /\bunited kingdom only\b/i,
  /\beu only\b/i, /\beurope only\b/i, /\baustralia only\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i,
  /\bmust be authorized to work in\b/i, /\bauthorized to work in the (us|uk|eu|canada|australia)\b/i,
  /\blocal work permit required\b/i, /\bwork permit required\b/i,
  /\bhybrid role\b/i, /\bhybrid position\b/i, /\bonsite\b/i, /\bon-site\b/i,
  /\boffice required\b/i, /\bin-office\b/i,
  /\bremote within [a-z ]{3,25} only\b/i,
  /\bfixed us (business )?hours\b/i, /\bfixed eu (business )?hours\b/i,
  /\bmust relocate\b/i, /\brelocation required\b/i,
  /\bno international\b/i
];

// Keep keywords — job must match at least one
const KEEP_KEYWORDS = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence', 'bi analyst', 'marketing analyst',
  'performance marketing', 'growth analyst', 'growth hacker',
  'ai marketing', 'ai automation', 'ai workflow',
  'machine learning', 'martech', 'marketing analytics',
  'automation specialist', 'analytics engineer',
  'digital marketing analyst', 'creative strategist',
  'seo analyst', 'paid media analyst', 'data',
  'analytics', 'tableau', 'power bi', 'sql analyst',
  'python analyst', 'marketing data'
];

const jobs = $input.all();
const results = [];

for (const item of jobs) {
  const job = item.json;
  const url = job.job_url;

  if (!url || existing.has(url)) continue;

  const fullText = `${job.job_title} ${job.location_text} ${job.description}`.toLowerCase();

  let hardRejected = false;
  let rejectReason = '';
  for (const pattern of REJECT_PATTERNS) {
    if (pattern.test(fullText)) {
      hardRejected = true;
      rejectReason = pattern.toString();
      break;
    }
  }
  if (hardRejected) continue;

  const titleDesc = `${job.job_title} ${job.description}`.toLowerCase();
  const hasKeyword = KEEP_KEYWORDS.some(kw => titleDesc.includes(kw));
  if (!hasKeyword) continue;

  results.push({ json: job });
}

return results;

