const allItems = $input.all();
const results = [];

const ASYNC_HIGH = ['async-first','async first','asynchronous','fully async','no meetings','own schedule'];
const ASYNC_MED = ['flexible hours','flexible schedule','flexible time','work when you want','across time zones','distributed team','remote-first','remote first','low meeting'];
const ASYNC_NONE = ['strict 9 to 5','9am-5pm est','9am-5pm pst','9am-5pm cet','fixed est hours','fixed pst hours','fixed cet hours','daily live calls required','must overlap full business day','core hours required','synchronous'];

const TIER1_ROLES = ['data analyst','data scientist','junior data scientist','bi analyst','business intelligence analyst','marketing analyst','performance marketing analyst','growth analyst','ai marketing','ai automation','ai workflow consultant','martech analyst','marketing analytics','creative strategist with data'];
const TIER2_ROLES = ['product analyst','operations analyst','digital marketing','seo analyst','ppc analyst','analytics engineer','customer success analyst','growth hacker','ecommerce analyst','data engineer'];

for (const item of allItems) {
  const job = { ...item.json };
  let aiResult = {};

  // Parse AI response from message content
  try {
    const rawContent = item.json.message?.content || item.json.content || item.json.text || '{}';
    const match = rawContent.match(/\{[\s\S]*\}/);
    aiResult = JSON.parse(match ? match[0] : '{}');
  } catch(e) {
    aiResult = { taiwan_eligible:'unclear', reason:'parse error', location_risk:'medium', timezone_risk:'medium', contractor_possible:'unclear', decision:'manual_check' };
  }

  const fullText = `${job.job_title} ${job.location_text} ${job.description} ${job.tags}`.toLowerCase();
  const titleLower = (job.job_title || '').toLowerCase();

  // Async level
  let async_level = 'unknown';
  if (ASYNC_NONE.some(k => fullText.includes(k))) {
    async_level = 'none';
  } else if (ASYNC_HIGH.some(k => fullText.includes(k))) {
    async_level = 'high';
  } else if (ASYNC_MED.some(k => fullText.includes(k))) {
    async_level = 'medium';
  } else {
    async_level = 'low';
  }

  // Skip if async is explicitly none
  if (async_level === 'none') {
    results.push({ json: { ...job, ...aiResult, async_level, role_category: 'unknown', score: 0, why_good_fit: 'Rejected: fixed timezone hours', decision_final: 'reject' } });
    continue;
  }

  // Role category
  let role_category = 'other';
  if (TIER1_ROLES.some(r => titleLower.includes(r))) role_category = 'tier1_primary';
  else if (TIER2_ROLES.some(r => titleLower.includes(r))) role_category = 'tier2_adjacent';

  // Score
  let score = 0;
  const eligible = aiResult.taiwan_eligible || 'unclear';
  const locRisk = aiResult.location_risk || 'medium';
  const tzRisk = aiResult.timezone_risk || 'medium';

  // Taiwan eligibility (0-40 pts)
  if (eligible === 'yes') {
    if (locRisk === 'low') score += 40;
    else if (locRisk === 'medium') score += 30;
    else score += 20;
  } else if (eligible === 'unclear') {
    score += 20;
  }

  // Async fit (0-25 pts)
  if (async_level === 'high') score += 25;
  else if (async_level === 'medium') score += 20;
  else if (fullText.includes('distributed')) score += 15;
  else if (fullText.includes('remote first') || fullText.includes('remote-first')) score += 10;

  // Role fit (0-25 pts)
  if (role_category === 'tier1_primary') score += 25;
  else if (role_category === 'tier2_adjacent') score += 15;

  // Salary (0-25 pts)
  const salaryStr = job.salary || '';
  const nums = (salaryStr.match(/[\d,]+/g) || []).map(n => parseInt(n.replace(/,/g,''),10)).filter(n => n > 100);
  if (nums.length > 0) {
    const topNum = Math.max(...nums);
    const isAnnual = salaryStr.match(/yr|year|annual|k\b/i) || topNum > 10000;
    const monthly = isAnnual ? topNum / 12 : topNum;
    if (monthly >= 5000) score += 25;
    else if (monthly >= 3000) score += 15;
    else score += 10;
  }

  // Why good fit
  const whyParts = [];
  if (eligible === 'yes') whyParts.push('Taiwan-eligible');
  if (async_level === 'high') whyParts.push('fully async');
  else if (async_level === 'medium') whyParts.push('flexible hours');
  if (role_category === 'tier1_primary') whyParts.push('direct match for Jerry\'s skills');
  else if (role_category === 'tier2_adjacent') whyParts.push('adjacent to Jerry\'s skills');
  if (aiResult.contractor_possible === 'yes') whyParts.push('contractor/EOR possible');
  if (tzRisk === 'low') whyParts.push('good timezone fit');

  results.push({
    json: {
      date_found: job.date_found,
      score,
      job_title: job.job_title,
      company: job.company,
      job_url: job.job_url,
      salary: job.salary,
      source: job.source,
      description: job.description,
      tags: job.tags,
      posted_date: job.posted_date,
      taiwan_eligible: eligible,
      taiwan_reason: aiResult.reason || '',
      location_risk: locRisk,
      timezone_risk: tzRisk,
      contractor_possible: aiResult.contractor_possible || 'unclear',
      async_level,
      role_category,
      why_good_fit: whyParts.join(', ') || 'Review manually',
      decision_final: aiResult.decision || 'manual_check',
      application_status: 'new',
      notes: '',
      cover_letter: ''
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const coverLetterText = item.json.message?.content || item.json.content || item.json.text || '';
  // Merge the cover letter back with the job data from the previous batch item
  // The AI node passes through the original json fields alongside the response
  results.push({
    json: {
      ...item.json,
      cover_letter: coverLetterText
    }
  });
}

return results;

