const allItems = $input.all();
const today = new Date().toISOString().split('T')[0];

if (!allItems || allItems.length === 0) {
  return [{ json: {
    subject: `Daily Taiwan Job Hunt — No jobs found (${today})`,
    body: `No Taiwan-eligible async remote jobs found today.\nThe workflow will run again tomorrow at 8:30 AM Taiwan time.`
  }}];
}

const jobs = allItems.map(i => i.json);
const topJobs = jobs.filter(j => Number(j.score) >= 70).sort((a, b) => Number(b.score) - Number(a.score)).slice(0, 10);
const manualJobs = jobs.filter(j => j.taiwan_eligible === 'unclear' && Number(j.score) >= 70);

const totalFound = jobs.length;
const totalTop = topJobs.length;
const topCount85 = topJobs.filter(j => Number(j.score) >= 85).length;

let body = `Daily Taiwan Eligible Async Remote Jobs\n`;
body += `${today}\n`;
body += `${'='.repeat(40)}\n\n`;
body += `Summary: ${totalTop} jobs scored 70+ | ${topCount85} scored 85+ | ${totalFound} total processed\n\n`;

if (topJobs.length > 0) {
  body += `TOP JOBS TODAY:\n${'─'.repeat(40)}\n\n`;
  topJobs.forEach((j, i) => {
    body += `${i + 1}. ${j.job_title}\n`;
    body += `   Company: ${j.company}\n`;
    body += `   Score: ${j.score}/100\n`;
    body += `   Taiwan eligible: ${j.taiwan_eligible}\n`;
    body += `   Reason: ${j.taiwan_reason}\n`;
    body += `   Async level: ${j.async_level}\n`;
    body += `   Timezone risk: ${j.timezone_risk}\n`;
    body += `   Salary: ${j.salary || 'Not listed'}\n`;
    body += `   Why it fits Jerry: ${j.why_good_fit}\n`;
    body += `   Apply: ${j.job_url}\n`;
    if (j.notes && j.notes.length > 10) body += `   Cover letter: Ready\n`;
    body += `\n`;
  });
} else {
  body += `No jobs scored 70 or above today.\n\n`;
}

if (manualJobs.length > 0) {
  body += `\nMANUAL CHECK (unclear Taiwan eligibility, score 70+):\n${'─'.repeat(40)}\n`;
  manualJobs.slice(0, 5).forEach((j, i) => {
    body += `${i + 1}. ${j.job_title} at ${j.company} — Score: ${j.score}\n`;
    body += `   ${j.taiwan_reason}\n`;
    body += `   ${j.job_url}\n\n`;
  });
}

// Rejection summary
const allRejected = $('Read Today Filtered Jobs').all().length > 0 ? [] : [];
body += `\nREJECTION SUMMARY:\n${'─'.repeat(40)}\n`;
body += `Total jobs scored below 70: ${totalFound - totalTop}\n`;
body += `(Check the Rejected sheet in Google Sheets for details)\n`;

body += `\n${'='.repeat(40)}\n`;
body += `Google Sheets: https://docs.google.com/spreadsheets/d/REPLACE_WITH_YOUR_GOOGLE_SHEET_ID\n`;

return [{
  json: {
    subject: `Daily Taiwan Job Hunt — ${totalTop} jobs found${topCount85 > 0 ? ` (${topCount85} high score!)` : ''} (${today})`,
    body
  }
}];
